    s->t_attrib = s->t_attrib_default;

    text_console_resize(s);



    if (chr->label) {

        char msg[128];

        int len;



        s->t_attrib.bgcol = COLOR_BLUE;

        len = snprintf(msg, sizeof(msg), "%s console\r\n", chr->label);

        console_puts(chr, (uint8_t*)msg, len);

        s->t_attrib = s->t_attrib_default;

    }



    qemu_chr_generic_open(chr);

    if (chr->init)

        chr->init(chr);

}

