{

    int i;



    /* flush current page */

    for (i = 0; i < s->nb_streams; i++)

        ogg_buffer_page(s, s->streams[i]->priv_data);



    ogg_write_pages(s, 1);



    for (i = 0; i < s->nb_streams; i++) {

