    QDict *qdict, *sub_qdict;



    /* Root can't be a list */

    qdict = keyval_parse("0=1", NULL, &err);

    error_free_or_abort(&err);

    g_assert(!qdict);



    /* List elements need not be in order */

    qdict = keyval_parse("list.0=null,list.2=zwei,list.1=eins",

