       s->error_count==3*s->mb_width*(s->avctx->skip_top + s->avctx->skip_bottom)) return;



    if(s->current_picture.motion_val[0] == NULL){

        av_log(s->avctx, AV_LOG_ERROR, "Warning MVs not available\n");



        for(i=0; i<2; i++){

            pic->ref_index[i]= av_mallocz(size * sizeof(uint8_t));

            pic->motion_val_base[i]= av_mallocz((size+4) * 2 * sizeof(uint16_t));

            pic->motion_val[i]= pic->motion_val_base[i]+4;

        }

        pic->motion_subsample_log2= 3;

        s->current_picture= *s->current_picture_ptr;

    }



    for(i=0; i<2; i++){

        if(pic->ref_index[i])

            memset(pic->ref_index[i], 0, size * sizeof(uint8_t));

    }



    if(s->avctx->debug&FF_DEBUG_ER){

        for(mb_y=0; mb_y<s->mb_height; mb_y++){

            for(mb_x=0; mb_x<s->mb_width; mb_x++){

                int status= s->error_status_table[mb_x + mb_y*s->mb_stride];



                av_log(s->avctx, AV_LOG_DEBUG, "%2X ", status);

            }

            av_log(s->avctx, AV_LOG_DEBUG, "\n");

        }

    }



#if 1

    /* handle overlapping slices */

    for(error_type=1; error_type<=3; error_type++){

        int end_ok=0;



        for(i=s->mb_num-1; i>=0; i--){

            const int mb_xy= s->mb_index2xy[i];

            int error= s->error_status_table[mb_xy];



            if(error&(1<<error_type))

                end_ok=1;

            if(error&(8<<error_type))

                end_ok=1;



            if(!end_ok)

                s->error_status_table[mb_xy]|= 1<<error_type;



            if(error&VP_START)

                end_ok=0;

        }

    }

#endif

#if 1

    /* handle slices with partitions of different length */

    if(s->partitioned_frame){

        int end_ok=0;



        for(i=s->mb_num-1; i>=0; i--){

            const int mb_xy= s->mb_index2xy[i];

            int error= s->error_status_table[mb_xy];



            if(error&AC_END)

                end_ok=0;

            if((error&MV_END) || (error&DC_END) || (error&AC_ERROR))

                end_ok=1;



            if(!end_ok)

                s->error_status_table[mb_xy]|= AC_ERROR;



            if(error&VP_START)

                end_ok=0;

        }

    }

#endif

    /* handle missing slices */

    if(s->error_recognition>=4){

        int end_ok=1;



        for(i=s->mb_num-2; i>=s->mb_width+100; i--){ //FIXME +100 hack

            const int mb_xy= s->mb_index2xy[i];

            int error1= s->error_status_table[mb_xy  ];

            int error2= s->error_status_table[s->mb_index2xy[i+1]];



            if(error1&VP_START)

                end_ok=1;



            if(   error2==(VP_START|DC_ERROR|AC_ERROR|MV_ERROR|AC_END|DC_END|MV_END)

               && error1!=(VP_START|DC_ERROR|AC_ERROR|MV_ERROR|AC_END|DC_END|MV_END)

               && ((error1&AC_END) || (error1&DC_END) || (error1&MV_END))){ //end & uninit

                end_ok=0;

            }



            if(!end_ok)

                s->error_status_table[mb_xy]|= DC_ERROR|AC_ERROR|MV_ERROR;

        }

    }



#if 1

    /* backward mark errors */

    distance=9999999;

    for(error_type=1; error_type<=3; error_type++){

        for(i=s->mb_num-1; i>=0; i--){

            const int mb_xy= s->mb_index2xy[i];

            int error= s->error_status_table[mb_xy];



            if(!s->mbskip_table[mb_xy]) //FIXME partition specific

                distance++;

            if(error&(1<<error_type))

                distance= 0;



            if(s->partitioned_frame){

                if(distance < threshold_part[error_type-1])

                    s->error_status_table[mb_xy]|= 1<<error_type;

            }else{

                if(distance < threshold)

                    s->error_status_table[mb_xy]|= 1<<error_type;

            }



            if(error&VP_START)

                distance= 9999999;

        }

    }

#endif



    /* forward mark errors */

    error=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        int old_error= s->error_status_table[mb_xy];



        if(old_error&VP_START)

            error= old_error& (DC_ERROR|AC_ERROR|MV_ERROR);

        else{

            error|= old_error& (DC_ERROR|AC_ERROR|MV_ERROR);

            s->error_status_table[mb_xy]|= error;

        }

    }

#if 1

    /* handle not partitioned case */

    if(!s->partitioned_frame){

        for(i=0; i<s->mb_num; i++){

            const int mb_xy= s->mb_index2xy[i];

            error= s->error_status_table[mb_xy];

            if(error&(AC_ERROR|DC_ERROR|MV_ERROR))

                error|= AC_ERROR|DC_ERROR|MV_ERROR;

            s->error_status_table[mb_xy]= error;

        }

    }

#endif



    dc_error= ac_error= mv_error=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        error= s->error_status_table[mb_xy];

        if(error&DC_ERROR) dc_error ++;

        if(error&AC_ERROR) ac_error ++;

        if(error&MV_ERROR) mv_error ++;

    }

    av_log(s->avctx, AV_LOG_INFO, "concealing %d DC, %d AC, %d MV errors\n", dc_error, ac_error, mv_error);



    is_intra_likely= is_intra_more_likely(s);



    /* set unknown mb-type to most likely */

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        error= s->error_status_table[mb_xy];

        if(!((error&DC_ERROR) && (error&MV_ERROR)))

            continue;



        if(is_intra_likely)

            s->current_picture.mb_type[mb_xy]= MB_TYPE_INTRA4x4;

        else

            s->current_picture.mb_type[mb_xy]= MB_TYPE_16x16 | MB_TYPE_L0;

    }



    /* handle inter blocks with damaged AC */

    for(mb_y=0; mb_y<s->mb_height; mb_y++){

        for(mb_x=0; mb_x<s->mb_width; mb_x++){

            const int mb_xy= mb_x + mb_y * s->mb_stride;

            const int mb_type= s->current_picture.mb_type[mb_xy];

            error= s->error_status_table[mb_xy];



            if(IS_INTRA(mb_type)) continue; //intra

            if(error&MV_ERROR) continue;              //inter with damaged MV

            if(!(error&AC_ERROR)) continue;           //undamaged inter



            s->mv_dir = MV_DIR_FORWARD;

            s->mb_intra=0;

            s->mb_skipped=0;

            if(IS_8X8(mb_type)){

                int mb_index= mb_x*2 + mb_y*2*s->b8_stride;

                int j;

                s->mv_type = MV_TYPE_8X8;

                for(j=0; j<4; j++){

                    s->mv[0][j][0] = s->current_picture.motion_val[0][ mb_index + (j&1) + (j>>1)*s->b8_stride ][0];

                    s->mv[0][j][1] = s->current_picture.motion_val[0][ mb_index + (j&1) + (j>>1)*s->b8_stride ][1];

                }

            }else{

                s->mv_type = MV_TYPE_16X16;

                s->mv[0][0][0] = s->current_picture.motion_val[0][ mb_x*2 + mb_y*2*s->b8_stride ][0];

                s->mv[0][0][1] = s->current_picture.motion_val[0][ mb_x*2 + mb_y*2*s->b8_stride ][1];

            }



            s->dsp.clear_blocks(s->block[0]);



            s->mb_x= mb_x;

            s->mb_y= mb_y;

            decode_mb(s);

        }

    }



    /* guess MVs */

    if(s->pict_type==FF_B_TYPE){

        for(mb_y=0; mb_y<s->mb_height; mb_y++){

            for(mb_x=0; mb_x<s->mb_width; mb_x++){

                int xy= mb_x*2 + mb_y*2*s->b8_stride;

                const int mb_xy= mb_x + mb_y * s->mb_stride;

                const int mb_type= s->current_picture.mb_type[mb_xy];

                error= s->error_status_table[mb_xy];



                if(IS_INTRA(mb_type)) continue;

                if(!(error&MV_ERROR)) continue;           //inter with undamaged MV

                if(!(error&AC_ERROR)) continue;           //undamaged inter



                s->mv_dir = MV_DIR_FORWARD|MV_DIR_BACKWARD;

                s->mb_intra=0;

                s->mv_type = MV_TYPE_16X16;

                s->mb_skipped=0;



                if(s->pp_time){

                    int time_pp= s->pp_time;

                    int time_pb= s->pb_time;



                    s->mv[0][0][0] = s->next_picture.motion_val[0][xy][0]*time_pb/time_pp;

                    s->mv[0][0][1] = s->next_picture.motion_val[0][xy][1]*time_pb/time_pp;

                    s->mv[1][0][0] = s->next_picture.motion_val[0][xy][0]*(time_pb - time_pp)/time_pp;

                    s->mv[1][0][1] = s->next_picture.motion_val[0][xy][1]*(time_pb - time_pp)/time_pp;

                }else{

                    s->mv[0][0][0]= 0;

                    s->mv[0][0][1]= 0;

                    s->mv[1][0][0]= 0;

                    s->mv[1][0][1]= 0;

                }



                s->dsp.clear_blocks(s->block[0]);

                s->mb_x= mb_x;

                s->mb_y= mb_y;

                decode_mb(s);

            }

        }

    }else

        guess_mv(s);



#if CONFIG_MPEG_XVMC_DECODER

    /* the filters below are not XvMC compatible, skip them */

    if(s->avctx->xvmc_acceleration) goto ec_clean;

#endif

    /* fill DC for inter blocks */

    for(mb_y=0; mb_y<s->mb_height; mb_y++){

        for(mb_x=0; mb_x<s->mb_width; mb_x++){

            int dc, dcu, dcv, y, n;

            int16_t *dc_ptr;

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy= mb_x + mb_y * s->mb_stride;

            const int mb_type= s->current_picture.mb_type[mb_xy];



            error= s->error_status_table[mb_xy];



            if(IS_INTRA(mb_type) && s->partitioned_frame) continue;

//            if(error&MV_ERROR) continue; //inter data damaged FIXME is this good?



            dest_y = s->current_picture.data[0] + mb_x*16 + mb_y*16*s->linesize;

            dest_cb= s->current_picture.data[1] + mb_x*8  + mb_y*8 *s->uvlinesize;

            dest_cr= s->current_picture.data[2] + mb_x*8  + mb_y*8 *s->uvlinesize;



            dc_ptr= &s->dc_val[0][mb_x*2 + mb_y*2*s->b8_stride];

            for(n=0; n<4; n++){

                dc=0;

                for(y=0; y<8; y++){

                    int x;

                    for(x=0; x<8; x++){

                       dc+= dest_y[x + (n&1)*8 + (y + (n>>1)*8)*s->linesize];

                    }

                }

                dc_ptr[(n&1) + (n>>1)*s->b8_stride]= (dc+4)>>3;

            }



            dcu=dcv=0;

            for(y=0; y<8; y++){

                int x;

                for(x=0; x<8; x++){

                    dcu+=dest_cb[x + y*(s->uvlinesize)];

                    dcv+=dest_cr[x + y*(s->uvlinesize)];

                }

            }

            s->dc_val[1][mb_x + mb_y*s->mb_stride]= (dcu+4)>>3;

            s->dc_val[2][mb_x + mb_y*s->mb_stride]= (dcv+4)>>3;

        }

    }

#if 1

    /* guess DC for damaged blocks */

    guess_dc(s, s->dc_val[0], s->mb_width*2, s->mb_height*2, s->b8_stride, 1);

    guess_dc(s, s->dc_val[1], s->mb_width  , s->mb_height  , s->mb_stride, 0);

    guess_dc(s, s->dc_val[2], s->mb_width  , s->mb_height  , s->mb_stride, 0);

#endif

    /* filter luma DC */

    filter181(s->dc_val[0], s->mb_width*2, s->mb_height*2, s->b8_stride);



#if 1

    /* render DC only intra */

    for(mb_y=0; mb_y<s->mb_height; mb_y++){

        for(mb_x=0; mb_x<s->mb_width; mb_x++){

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy= mb_x + mb_y * s->mb_stride;

            const int mb_type= s->current_picture.mb_type[mb_xy];



            error= s->error_status_table[mb_xy];



            if(IS_INTER(mb_type)) continue;

            if(!(error&AC_ERROR)) continue;              //undamaged



            dest_y = s->current_picture.data[0] + mb_x*16 + mb_y*16*s->linesize;

            dest_cb= s->current_picture.data[1] + mb_x*8  + mb_y*8 *s->uvlinesize;

            dest_cr= s->current_picture.data[2] + mb_x*8  + mb_y*8 *s->uvlinesize;



            put_dc(s, dest_y, dest_cb, dest_cr, mb_x, mb_y);

        }

    }

#endif



    if(s->avctx->error_concealment&FF_EC_DEBLOCK){

        /* filter horizontal block boundaries */

        h_block_filter(s, s->current_picture.data[0], s->mb_width*2, s->mb_height*2, s->linesize  , 1);

        h_block_filter(s, s->current_picture.data[1], s->mb_width  , s->mb_height  , s->uvlinesize, 0);

        h_block_filter(s, s->current_picture.data[2], s->mb_width  , s->mb_height  , s->uvlinesize, 0);



        /* filter vertical block boundaries */

        v_block_filter(s, s->current_picture.data[0], s->mb_width*2, s->mb_height*2, s->linesize  , 1);

        v_block_filter(s, s->current_picture.data[1], s->mb_width  , s->mb_height  , s->uvlinesize, 0);

        v_block_filter(s, s->current_picture.data[2], s->mb_width  , s->mb_height  , s->uvlinesize, 0);

    }



#if CONFIG_MPEG_XVMC_DECODER

ec_clean:

#endif

    /* clean a few tables */

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[i];

        int error= s->error_status_table[mb_xy];



        if(s->pict_type!=FF_B_TYPE && (error&(DC_ERROR|MV_ERROR|AC_ERROR))){

            s->mbskip_table[mb_xy]=0;

        }

        s->mbintra_table[mb_xy]=1;

    }

}

demonstrations.func:
void ff_er_frame_end(ERContext *s)

{

    int *linesize = s->cur_pic->f.linesize;

    int i, mb_x, mb_y, error, error_type, dc_error, mv_error, ac_error;

    int distance;

    int threshold_part[4] = { 100, 100, 100 };

    int threshold = 50;

    int is_intra_likely;

    int size = s->b8_stride * 2 * s->mb_height;



    /* We do not support ER of field pictures yet,

     * though it should not crash if enabled. */

    if (!s->avctx->error_concealment || s->error_count == 0            ||

        s->avctx->lowres                                               ||

        s->avctx->hwaccel                                              ||

        s->avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU          ||

        !s->cur_pic || s->cur_pic->field_picture                               ||

        s->error_count == 3 * s->mb_width *

                          (s->avctx->skip_top + s->avctx->skip_bottom)) {

        return;

    }

    for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

        int status = s->error_status_table[mb_x + (s->mb_height - 1) * s->mb_stride];

        if (status != 0x7F)

            break;

    }



    if (   mb_x == s->mb_width

        && s->avctx->codec_id == AV_CODEC_ID_MPEG2VIDEO

        && (s->avctx->height&16)

        && s->error_count == 3 * s->mb_width * (s->avctx->skip_top + s->avctx->skip_bottom + 1)

    ) {

        av_log(s->avctx, AV_LOG_DEBUG, "ignoring last missing slice\n");

        return;

    }



    if (s->last_pic) {

        if (s->last_pic->f.width  != s->cur_pic->f.width  ||

            s->last_pic->f.height != s->cur_pic->f.height ||

            s->last_pic->f.format != s->cur_pic->f.format) {

            av_log(s->avctx, AV_LOG_WARNING, "Cannot use previous picture in error concealment\n");

            s->last_pic = NULL;

        }

    }

    if (s->next_pic) {

        if (s->next_pic->f.width  != s->cur_pic->f.width  ||

            s->next_pic->f.height != s->cur_pic->f.height ||

            s->next_pic->f.format != s->cur_pic->f.format) {

            av_log(s->avctx, AV_LOG_WARNING, "Cannot use next picture in error concealment\n");

            s->next_pic = NULL;

        }

    }



    if (s->cur_pic->motion_val[0] == NULL) {

        av_log(s->avctx, AV_LOG_ERROR, "Warning MVs not available\n");



        for (i = 0; i < 2; i++) {

            s->cur_pic->ref_index_buf[i]  = av_buffer_allocz(s->mb_stride * s->mb_height * 4 * sizeof(uint8_t));

            s->cur_pic->motion_val_buf[i] = av_buffer_allocz((size + 4) * 2 * sizeof(uint16_t));

            if (!s->cur_pic->ref_index_buf[i] || !s->cur_pic->motion_val_buf[i])

                break;

            s->cur_pic->ref_index[i]  = s->cur_pic->ref_index_buf[i]->data;

            s->cur_pic->motion_val[i] = (int16_t (*)[2])s->cur_pic->motion_val_buf[i]->data + 4;

        }

        if (i < 2) {

            for (i = 0; i < 2; i++) {

                av_buffer_unref(&s->cur_pic->ref_index_buf[i]);

                av_buffer_unref(&s->cur_pic->motion_val_buf[i]);

                s->cur_pic->ref_index[i]  = NULL;

                s->cur_pic->motion_val[i] = NULL;

            }

            return;

        }

    }



    if (s->avctx->debug & FF_DEBUG_ER) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                int status = s->error_status_table[mb_x + mb_y * s->mb_stride];



                av_log(s->avctx, AV_LOG_DEBUG, "%2X ", status);

            }

            av_log(s->avctx, AV_LOG_DEBUG, "\n");

        }

    }



#if 1

    /* handle overlapping slices */

    for (error_type = 1; error_type <= 3; error_type++) {

        int end_ok = 0;



        for (i = s->mb_num - 1; i >= 0; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int error       = s->error_status_table[mb_xy];



            if (error & (1 << error_type))

                end_ok = 1;

            if (error & (8 << error_type))

                end_ok = 1;



            if (!end_ok)

                s->error_status_table[mb_xy] |= 1 << error_type;



            if (error & VP_START)

                end_ok = 0;

        }

    }

#endif

#if 1

    /* handle slices with partitions of different length */

    if (s->partitioned_frame) {

        int end_ok = 0;



        for (i = s->mb_num - 1; i >= 0; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int error       = s->error_status_table[mb_xy];



            if (error & ER_AC_END)

                end_ok = 0;

            if ((error & ER_MV_END) ||

                (error & ER_DC_END) ||

                (error & ER_AC_ERROR))

                end_ok = 1;



            if (!end_ok)

                s->error_status_table[mb_xy]|= ER_AC_ERROR;



            if (error & VP_START)

                end_ok = 0;

        }

    }

#endif

    /* handle missing slices */

    if (s->avctx->err_recognition & AV_EF_EXPLODE) {

        int end_ok = 1;



        // FIXME + 100 hack

        for (i = s->mb_num - 2; i >= s->mb_width + 100; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int error1 = s->error_status_table[mb_xy];

            int error2 = s->error_status_table[s->mb_index2xy[i + 1]];



            if (error1 & VP_START)

                end_ok = 1;



            if (error2 == (VP_START | ER_MB_ERROR | ER_MB_END) &&

                error1 != (VP_START | ER_MB_ERROR | ER_MB_END) &&

                ((error1 & ER_AC_END) || (error1 & ER_DC_END) ||

                (error1 & ER_MV_END))) {

                // end & uninit

                end_ok = 0;

            }



            if (!end_ok)

                s->error_status_table[mb_xy] |= ER_MB_ERROR;

        }

    }



#if 1

    /* backward mark errors */

    distance = 9999999;

    for (error_type = 1; error_type <= 3; error_type++) {

        for (i = s->mb_num - 1; i >= 0; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int       error = s->error_status_table[mb_xy];



            if (!s->mbskip_table[mb_xy]) // FIXME partition specific

                distance++;

            if (error & (1 << error_type))

                distance = 0;



            if (s->partitioned_frame) {

                if (distance < threshold_part[error_type - 1])

                    s->error_status_table[mb_xy] |= 1 << error_type;

            } else {

                if (distance < threshold)

                    s->error_status_table[mb_xy] |= 1 << error_type;

            }



            if (error & VP_START)

                distance = 9999999;

        }

    }

#endif



    /* forward mark errors */

    error = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int old_error   = s->error_status_table[mb_xy];



        if (old_error & VP_START) {

            error = old_error & ER_MB_ERROR;

        } else {

            error |= old_error & ER_MB_ERROR;

            s->error_status_table[mb_xy] |= error;

        }

    }

#if 1

    /* handle not partitioned case */

    if (!s->partitioned_frame) {

        for (i = 0; i < s->mb_num; i++) {

            const int mb_xy = s->mb_index2xy[i];

            error = s->error_status_table[mb_xy];

            if (error & ER_MB_ERROR)

                error |= ER_MB_ERROR;

            s->error_status_table[mb_xy] = error;

        }

    }

#endif



    dc_error = ac_error = mv_error = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        error = s->error_status_table[mb_xy];

        if (error & ER_DC_ERROR)

            dc_error++;

        if (error & ER_AC_ERROR)

            ac_error++;

        if (error & ER_MV_ERROR)

            mv_error++;

    }

    av_log(s->avctx, AV_LOG_INFO, "concealing %d DC, %d AC, %d MV errors in %c frame\n",

           dc_error, ac_error, mv_error, av_get_picture_type_char(s->cur_pic->f.pict_type));



    is_intra_likely = is_intra_more_likely(s);



    /* set unknown mb-type to most likely */

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        error = s->error_status_table[mb_xy];

        if (!((error & ER_DC_ERROR) && (error & ER_MV_ERROR)))

            continue;



        if (is_intra_likely)

            s->cur_pic->mb_type[mb_xy] = MB_TYPE_INTRA4x4;

        else

            s->cur_pic->mb_type[mb_xy] = MB_TYPE_16x16 | MB_TYPE_L0;

    }



    // change inter to intra blocks if no reference frames are available

    if (!(s->last_pic && s->last_pic->f.data[0]) &&

        !(s->next_pic && s->next_pic->f.data[0]))

        for (i = 0; i < s->mb_num; i++) {

            const int mb_xy = s->mb_index2xy[i];

            if (!IS_INTRA(s->cur_pic->mb_type[mb_xy]))

                s->cur_pic->mb_type[mb_xy] = MB_TYPE_INTRA4x4;

        }



    /* handle inter blocks with damaged AC */

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            const int mb_xy   = mb_x + mb_y * s->mb_stride;

            const int mb_type = s->cur_pic->mb_type[mb_xy];

            const int dir     = !(s->last_pic && s->last_pic->f.data[0]);

            const int mv_dir  = dir ? MV_DIR_BACKWARD : MV_DIR_FORWARD;

            int mv_type;



            error = s->error_status_table[mb_xy];



            if (IS_INTRA(mb_type))

                continue; // intra

            if (error & ER_MV_ERROR)

                continue; // inter with damaged MV

            if (!(error & ER_AC_ERROR))

                continue; // undamaged inter



            if (IS_8X8(mb_type)) {

                int mb_index = mb_x * 2 + mb_y * 2 * s->b8_stride;

                int j;

                mv_type = MV_TYPE_8X8;

                for (j = 0; j < 4; j++) {

                    s->mv[0][j][0] = s->cur_pic->motion_val[dir][mb_index + (j & 1) + (j >> 1) * s->b8_stride][0];

                    s->mv[0][j][1] = s->cur_pic->motion_val[dir][mb_index + (j & 1) + (j >> 1) * s->b8_stride][1];

                }

            } else {

                mv_type     = MV_TYPE_16X16;

                s->mv[0][0][0] = s->cur_pic->motion_val[dir][mb_x * 2 + mb_y * 2 * s->b8_stride][0];

                s->mv[0][0][1] = s->cur_pic->motion_val[dir][mb_x * 2 + mb_y * 2 * s->b8_stride][1];

            }



            s->decode_mb(s->opaque, 0 /* FIXME h264 partitioned slices need this set */,

                         mv_dir, mv_type, &s->mv, mb_x, mb_y, 0, 0);

        }

    }



    /* guess MVs */

    if (s->cur_pic->f.pict_type == AV_PICTURE_TYPE_B) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                int       xy      = mb_x * 2 + mb_y * 2 * s->b8_stride;

                const int mb_xy   = mb_x + mb_y * s->mb_stride;

                const int mb_type = s->cur_pic->mb_type[mb_xy];

                int mv_dir = MV_DIR_FORWARD | MV_DIR_BACKWARD;



                error = s->error_status_table[mb_xy];



                if (IS_INTRA(mb_type))

                    continue;

                if (!(error & ER_MV_ERROR))

                    continue; // inter with undamaged MV

                if (!(error & ER_AC_ERROR))

                    continue; // undamaged inter



                if (!(s->last_pic && s->last_pic->f.data[0]))

                    mv_dir &= ~MV_DIR_FORWARD;

                if (!(s->next_pic && s->next_pic->f.data[0]))

                    mv_dir &= ~MV_DIR_BACKWARD;



                if (s->pp_time) {

                    int time_pp = s->pp_time;

                    int time_pb = s->pb_time;



                    av_assert0(s->avctx->codec_id != AV_CODEC_ID_H264);

                    ff_thread_await_progress(&s->next_pic->tf, mb_y, 0);



                    s->mv[0][0][0] = s->next_pic->motion_val[0][xy][0] *  time_pb            / time_pp;

                    s->mv[0][0][1] = s->next_pic->motion_val[0][xy][1] *  time_pb            / time_pp;

                    s->mv[1][0][0] = s->next_pic->motion_val[0][xy][0] * (time_pb - time_pp) / time_pp;

                    s->mv[1][0][1] = s->next_pic->motion_val[0][xy][1] * (time_pb - time_pp) / time_pp;

                } else {

                    s->mv[0][0][0] = 0;

                    s->mv[0][0][1] = 0;

                    s->mv[1][0][0] = 0;

                    s->mv[1][0][1] = 0;

                }



                s->decode_mb(s->opaque, 0, mv_dir, MV_TYPE_16X16, &s->mv,

                             mb_x, mb_y, 0, 0);

            }

        }

    } else

        guess_mv(s);



#if FF_API_XVMC

FF_DISABLE_DEPRECATION_WARNINGS

    /* the filters below are not XvMC compatible, skip them */

    if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration)

        goto ec_clean;

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */

    /* fill DC for inter blocks */

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            int dc, dcu, dcv, y, n;

            int16_t *dc_ptr;

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy   = mb_x + mb_y * s->mb_stride;

            const int mb_type = s->cur_pic->mb_type[mb_xy];



            error = s->error_status_table[mb_xy];



            if (IS_INTRA(mb_type) && s->partitioned_frame)

                continue;

            // if (error & ER_MV_ERROR)

            //     continue; // inter data damaged FIXME is this good?



            dest_y  = s->cur_pic->f.data[0] + mb_x * 16 + mb_y * 16 * linesize[0];

            dest_cb = s->cur_pic->f.data[1] + mb_x *  8 + mb_y *  8 * linesize[1];

            dest_cr = s->cur_pic->f.data[2] + mb_x *  8 + mb_y *  8 * linesize[2];



            dc_ptr = &s->dc_val[0][mb_x * 2 + mb_y * 2 * s->b8_stride];

            for (n = 0; n < 4; n++) {

                dc = 0;

                for (y = 0; y < 8; y++) {

                    int x;

                    for (x = 0; x < 8; x++)

                       dc += dest_y[x + (n & 1) * 8 +

                             (y + (n >> 1) * 8) * linesize[0]];

                }

                dc_ptr[(n & 1) + (n >> 1) * s->b8_stride] = (dc + 4) >> 3;

            }



            dcu = dcv = 0;

            for (y = 0; y < 8; y++) {

                int x;

                for (x = 0; x < 8; x++) {

                    dcu += dest_cb[x + y * linesize[1]];

                    dcv += dest_cr[x + y * linesize[2]];

                }

            }

            s->dc_val[1][mb_x + mb_y * s->mb_stride] = (dcu + 4) >> 3;

            s->dc_val[2][mb_x + mb_y * s->mb_stride] = (dcv + 4) >> 3;

        }

    }

#if 1

    /* guess DC for damaged blocks */

    guess_dc(s, s->dc_val[0], s->mb_width*2, s->mb_height*2, s->b8_stride, 1);

    guess_dc(s, s->dc_val[1], s->mb_width  , s->mb_height  , s->mb_stride, 0);

    guess_dc(s, s->dc_val[2], s->mb_width  , s->mb_height  , s->mb_stride, 0);

#endif



    /* filter luma DC */

    filter181(s->dc_val[0], s->mb_width * 2, s->mb_height * 2, s->b8_stride);



#if 1

    /* render DC only intra */

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy   = mb_x + mb_y * s->mb_stride;

            const int mb_type = s->cur_pic->mb_type[mb_xy];



            error = s->error_status_table[mb_xy];



            if (IS_INTER(mb_type))

                continue;

            if (!(error & ER_AC_ERROR))

                continue; // undamaged



            dest_y  = s->cur_pic->f.data[0] + mb_x * 16 + mb_y * 16 * linesize[0];

            dest_cb = s->cur_pic->f.data[1] + mb_x *  8 + mb_y *  8 * linesize[1];

            dest_cr = s->cur_pic->f.data[2] + mb_x *  8 + mb_y *  8 * linesize[2];



            put_dc(s, dest_y, dest_cb, dest_cr, mb_x, mb_y);

        }

    }

#endif



    if (s->avctx->error_concealment & FF_EC_DEBLOCK) {

        /* filter horizontal block boundaries */

        h_block_filter(s, s->cur_pic->f.data[0], s->mb_width * 2,

                       s->mb_height * 2, linesize[0], 1);

        h_block_filter(s, s->cur_pic->f.data[1], s->mb_width,

                       s->mb_height, linesize[1], 0);

        h_block_filter(s, s->cur_pic->f.data[2], s->mb_width,

                       s->mb_height, linesize[2], 0);



        /* filter vertical block boundaries */

        v_block_filter(s, s->cur_pic->f.data[0], s->mb_width * 2,

                       s->mb_height * 2, linesize[0], 1);

        v_block_filter(s, s->cur_pic->f.data[1], s->mb_width,

                       s->mb_height, linesize[1], 0);

        v_block_filter(s, s->cur_pic->f.data[2], s->mb_width,

                       s->mb_height, linesize[2], 0);

    }



ec_clean:

    /* clean a few tables */

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int       error = s->error_status_table[mb_xy];



        if (s->cur_pic->f.pict_type != AV_PICTURE_TYPE_B &&

            (error & (ER_DC_ERROR | ER_MV_ERROR | ER_AC_ERROR))) {

            s->mbskip_table[mb_xy] = 0;

        }

        s->mbintra_table[mb_xy] = 1;

    }

    s->cur_pic = NULL;

    s->next_pic    = NULL;

    s->last_pic    = NULL;

}

demonstrations_pair.func:
static void guess_mv(MpegEncContext *s){

    uint8_t fixed[s->mb_stride * s->mb_height];

#define MV_FROZEN    3

#define MV_CHANGED   2

#define MV_UNCHANGED 1

    const int mb_stride = s->mb_stride;

    const int mb_width = s->mb_width;

    const int mb_height= s->mb_height;

    int i, depth, num_avail;

    int mb_x, mb_y, mot_step, mot_stride;



    set_mv_strides(s, &mot_step, &mot_stride);



    num_avail=0;

    for(i=0; i<s->mb_num; i++){

        const int mb_xy= s->mb_index2xy[ i ];

        int f=0;

        int error= s->error_status_table[mb_xy];



        if(IS_INTRA(s->current_picture.mb_type[mb_xy])) f=MV_FROZEN; //intra //FIXME check

        if(!(error&MV_ERROR)) f=MV_FROZEN;           //inter with undamaged MV



        fixed[mb_xy]= f;

        if(f==MV_FROZEN)

            num_avail++;

    }



    if((!(s->avctx->error_concealment&FF_EC_GUESS_MVS)) || num_avail <= mb_width/2){

        for(mb_y=0; mb_y<s->mb_height; mb_y++){

            for(mb_x=0; mb_x<s->mb_width; mb_x++){

                const int mb_xy= mb_x + mb_y*s->mb_stride;



                if(IS_INTRA(s->current_picture.mb_type[mb_xy]))  continue;

                if(!(s->error_status_table[mb_xy]&MV_ERROR)) continue;



                s->mv_dir = s->last_picture.data[0] ? MV_DIR_FORWARD : MV_DIR_BACKWARD;

                s->mb_intra=0;

                s->mv_type = MV_TYPE_16X16;

                s->mb_skipped=0;



                s->dsp.clear_blocks(s->block[0]);



                s->mb_x= mb_x;

                s->mb_y= mb_y;

                s->mv[0][0][0]= 0;

                s->mv[0][0][1]= 0;

                decode_mb(s, 0);

            }

        }

        return;

    }



    for(depth=0;; depth++){

        int changed, pass, none_left;



        none_left=1;

        changed=1;

        for(pass=0; (changed || pass<2) && pass<10; pass++){

            int mb_x, mb_y;

int score_sum=0;



            changed=0;

            for(mb_y=0; mb_y<s->mb_height; mb_y++){

                for(mb_x=0; mb_x<s->mb_width; mb_x++){

                    const int mb_xy= mb_x + mb_y*s->mb_stride;

                    int mv_predictor[8][2]={{0}};

                    int ref[8]={0};

                    int pred_count=0;

                    int j;

                    int best_score=256*256*256*64;

                    int best_pred=0;

                    const int mot_index= (mb_x + mb_y*mot_stride) * mot_step;

                    int prev_x, prev_y, prev_ref;



                    if((mb_x^mb_y^pass)&1) continue;



                    if(fixed[mb_xy]==MV_FROZEN) continue;

                    assert(!IS_INTRA(s->current_picture.mb_type[mb_xy]));

                    assert(s->last_picture_ptr && s->last_picture_ptr->data[0]);



                    j=0;

                    if(mb_x>0           && fixed[mb_xy-1        ]==MV_FROZEN) j=1;

                    if(mb_x+1<mb_width  && fixed[mb_xy+1        ]==MV_FROZEN) j=1;

                    if(mb_y>0           && fixed[mb_xy-mb_stride]==MV_FROZEN) j=1;

                    if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]==MV_FROZEN) j=1;

                    if(j==0) continue;



                    j=0;

                    if(mb_x>0           && fixed[mb_xy-1        ]==MV_CHANGED) j=1;

                    if(mb_x+1<mb_width  && fixed[mb_xy+1        ]==MV_CHANGED) j=1;

                    if(mb_y>0           && fixed[mb_xy-mb_stride]==MV_CHANGED) j=1;

                    if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]==MV_CHANGED) j=1;

                    if(j==0 && pass>1) continue;



                    none_left=0;



                    if(mb_x>0 && fixed[mb_xy-1]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index - mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index - mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy-1)];

                        pred_count++;

                    }

                    if(mb_x+1<mb_width && fixed[mb_xy+1]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index + mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index + mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy+1)];

                        pred_count++;

                    }

                    if(mb_y>0 && fixed[mb_xy-mb_stride]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index - mot_stride*mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index - mot_stride*mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy-s->mb_stride)];

                        pred_count++;

                    }

                    if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]){

                        mv_predictor[pred_count][0]= s->current_picture.motion_val[0][mot_index + mot_stride*mot_step][0];

                        mv_predictor[pred_count][1]= s->current_picture.motion_val[0][mot_index + mot_stride*mot_step][1];

                        ref         [pred_count]   = s->current_picture.ref_index[0][4*(mb_xy+s->mb_stride)];

                        pred_count++;

                    }

                    if(pred_count==0) continue;



                    if(pred_count>1){

                        int sum_x=0, sum_y=0, sum_r=0;

                        int max_x, max_y, min_x, min_y, max_r, min_r;



                        for(j=0; j<pred_count; j++){

                            sum_x+= mv_predictor[j][0];

                            sum_y+= mv_predictor[j][1];

                            sum_r+= ref[j];

                            if(j && ref[j] != ref[j-1])

                                goto skip_mean_and_median;

                        }



                        /* mean */

                        mv_predictor[pred_count][0] = sum_x/j;

                        mv_predictor[pred_count][1] = sum_y/j;

                        ref         [pred_count]    = sum_r/j;



                        /* median */

                        if(pred_count>=3){

                            min_y= min_x= min_r= 99999;

                            max_y= max_x= max_r=-99999;

                        }else{

                            min_x=min_y=max_x=max_y=min_r=max_r=0;

                        }

                        for(j=0; j<pred_count; j++){

                            max_x= FFMAX(max_x, mv_predictor[j][0]);

                            max_y= FFMAX(max_y, mv_predictor[j][1]);

                            max_r= FFMAX(max_r, ref[j]);

                            min_x= FFMIN(min_x, mv_predictor[j][0]);

                            min_y= FFMIN(min_y, mv_predictor[j][1]);

                            min_r= FFMIN(min_r, ref[j]);

                        }

                        mv_predictor[pred_count+1][0] = sum_x - max_x - min_x;

                        mv_predictor[pred_count+1][1] = sum_y - max_y - min_y;

                        ref         [pred_count+1]    = sum_r - max_r - min_r;



                        if(pred_count==4){

                            mv_predictor[pred_count+1][0] /= 2;

                            mv_predictor[pred_count+1][1] /= 2;

                            ref         [pred_count+1]    /= 2;

                        }

                        pred_count+=2;

                    }

skip_mean_and_median:



                    /* zero MV */

                    pred_count++;



                    if (!fixed[mb_xy]) {

                        if (s->avctx->codec_id == CODEC_ID_H264) {

                            // FIXME

                        } else {

                            ff_thread_await_progress((AVFrame *) s->last_picture_ptr,

                                                     mb_y, 0);

                        }

                        if (!s->last_picture.motion_val[0] ||

                            !s->last_picture.ref_index[0])

                            goto skip_last_mv;

                        prev_x = s->last_picture.motion_val[0][mot_index][0];

                        prev_y = s->last_picture.motion_val[0][mot_index][1];

                        prev_ref = s->last_picture.ref_index[0][4*mb_xy];

                    } else {

                        prev_x = s->current_picture.motion_val[0][mot_index][0];

                        prev_y = s->current_picture.motion_val[0][mot_index][1];

                        prev_ref = s->current_picture.ref_index[0][4*mb_xy];

                    }



                    /* last MV */

                    mv_predictor[pred_count][0]= prev_x;

                    mv_predictor[pred_count][1]= prev_y;

                    ref         [pred_count]   = prev_ref;

                    pred_count++;




                    s->mv_dir = MV_DIR_FORWARD;

                    s->mb_intra=0;

                    s->mv_type = MV_TYPE_16X16;

                    s->mb_skipped=0;



                    s->dsp.clear_blocks(s->block[0]);



                    s->mb_x= mb_x;

                    s->mb_y= mb_y;



                    for(j=0; j<pred_count; j++){

                        int score=0;

                        uint8_t *src= s->current_picture.data[0] + mb_x*16 + mb_y*16*s->linesize;



                        s->current_picture.motion_val[0][mot_index][0]= s->mv[0][0][0]= mv_predictor[j][0];

                        s->current_picture.motion_val[0][mot_index][1]= s->mv[0][0][1]= mv_predictor[j][1];



                        if(ref[j]<0) //predictor intra or otherwise not available

                            continue;



                        decode_mb(s, ref[j]);



                        if(mb_x>0 && fixed[mb_xy-1]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k*s->linesize-1 ]-src[k*s->linesize   ]);

                        }

                        if(mb_x+1<mb_width && fixed[mb_xy+1]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k*s->linesize+15]-src[k*s->linesize+16]);

                        }

                        if(mb_y>0 && fixed[mb_xy-mb_stride]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k-s->linesize   ]-src[k               ]);

                        }

                        if(mb_y+1<mb_height && fixed[mb_xy+mb_stride]){

                            int k;

                            for(k=0; k<16; k++)

                                score += FFABS(src[k+s->linesize*15]-src[k+s->linesize*16]);

                        }



                        if(score <= best_score){ // <= will favor the last MV

                            best_score= score;

                            best_pred= j;

                        }

                    }

score_sum+= best_score;

                    s->mv[0][0][0]= mv_predictor[best_pred][0];

                    s->mv[0][0][1]= mv_predictor[best_pred][1];



                    for(i=0; i<mot_step; i++)

                        for(j=0; j<mot_step; j++){

                            s->current_picture.motion_val[0][mot_index+i+j*mot_stride][0]= s->mv[0][0][0];

                            s->current_picture.motion_val[0][mot_index+i+j*mot_stride][1]= s->mv[0][0][1];

                        }



                    decode_mb(s, ref[best_pred]);





                    if(s->mv[0][0][0] != prev_x || s->mv[0][0][1] != prev_y){

                        fixed[mb_xy]=MV_CHANGED;

                        changed++;

                    }else

                        fixed[mb_xy]=MV_UNCHANGED;

                }

            }



//            printf(".%d/%d", changed, score_sum); fflush(stdout);

        }



        if(none_left)

            return;



        for(i=0; i<s->mb_num; i++){

            int mb_xy= s->mb_index2xy[i];

            if(fixed[mb_xy])

                fixed[mb_xy]=MV_FROZEN;

        }

//        printf(":"); fflush(stdout);

    }

}

void ff_er_frame_end(ERContext *s)

{

    int *linesize = s->cur_pic->f.linesize;

    int i, mb_x, mb_y, error, error_type, dc_error, mv_error, ac_error;

    int distance;

    int threshold_part[4] = { 100, 100, 100 };

    int threshold = 50;

    int is_intra_likely;

    int size = s->b8_stride * 2 * s->mb_height;



    /* We do not support ER of field pictures yet,

     * though it should not crash if enabled. */

    if (!s->avctx->error_concealment || s->error_count == 0            ||

        s->avctx->lowres                                               ||

        s->avctx->hwaccel                                              ||

        s->avctx->codec->capabilities&CODEC_CAP_HWACCEL_VDPAU          ||

        !s->cur_pic || s->cur_pic->field_picture                               ||

        s->error_count == 3 * s->mb_width *

                          (s->avctx->skip_top + s->avctx->skip_bottom)) {

        return;

    }

    for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

        int status = s->error_status_table[mb_x + (s->mb_height - 1) * s->mb_stride];

        if (status != 0x7F)

            break;

    }



    if (   mb_x == s->mb_width

        && s->avctx->codec_id == AV_CODEC_ID_MPEG2VIDEO

        && (s->avctx->height&16)

        && s->error_count == 3 * s->mb_width * (s->avctx->skip_top + s->avctx->skip_bottom + 1)

    ) {

        av_log(s->avctx, AV_LOG_DEBUG, "ignoring last missing slice\n");

        return;

    }



    if (s->last_pic) {

        if (s->last_pic->f.width  != s->cur_pic->f.width  ||

            s->last_pic->f.height != s->cur_pic->f.height ||

            s->last_pic->f.format != s->cur_pic->f.format) {

            av_log(s->avctx, AV_LOG_WARNING, "Cannot use previous picture in error concealment\n");

            s->last_pic = NULL;

        }

    }

    if (s->next_pic) {

        if (s->next_pic->f.width  != s->cur_pic->f.width  ||

            s->next_pic->f.height != s->cur_pic->f.height ||

            s->next_pic->f.format != s->cur_pic->f.format) {

            av_log(s->avctx, AV_LOG_WARNING, "Cannot use next picture in error concealment\n");

            s->next_pic = NULL;

        }

    }



    if (s->cur_pic->motion_val[0] == NULL) {

        av_log(s->avctx, AV_LOG_ERROR, "Warning MVs not available\n");



        for (i = 0; i < 2; i++) {

            s->cur_pic->ref_index_buf[i]  = av_buffer_allocz(s->mb_stride * s->mb_height * 4 * sizeof(uint8_t));

            s->cur_pic->motion_val_buf[i] = av_buffer_allocz((size + 4) * 2 * sizeof(uint16_t));

            if (!s->cur_pic->ref_index_buf[i] || !s->cur_pic->motion_val_buf[i])

                break;

            s->cur_pic->ref_index[i]  = s->cur_pic->ref_index_buf[i]->data;

            s->cur_pic->motion_val[i] = (int16_t (*)[2])s->cur_pic->motion_val_buf[i]->data + 4;

        }

        if (i < 2) {

            for (i = 0; i < 2; i++) {

                av_buffer_unref(&s->cur_pic->ref_index_buf[i]);

                av_buffer_unref(&s->cur_pic->motion_val_buf[i]);

                s->cur_pic->ref_index[i]  = NULL;

                s->cur_pic->motion_val[i] = NULL;

            }

            return;

        }

    }



    if (s->avctx->debug & FF_DEBUG_ER) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                int status = s->error_status_table[mb_x + mb_y * s->mb_stride];



                av_log(s->avctx, AV_LOG_DEBUG, "%2X ", status);

            }

            av_log(s->avctx, AV_LOG_DEBUG, "\n");

        }

    }



#if 1

    /* handle overlapping slices */

    for (error_type = 1; error_type <= 3; error_type++) {

        int end_ok = 0;



        for (i = s->mb_num - 1; i >= 0; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int error       = s->error_status_table[mb_xy];



            if (error & (1 << error_type))

                end_ok = 1;

            if (error & (8 << error_type))

                end_ok = 1;



            if (!end_ok)

                s->error_status_table[mb_xy] |= 1 << error_type;



            if (error & VP_START)

                end_ok = 0;

        }

    }

#endif

#if 1

    /* handle slices with partitions of different length */

    if (s->partitioned_frame) {

        int end_ok = 0;



        for (i = s->mb_num - 1; i >= 0; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int error       = s->error_status_table[mb_xy];



            if (error & ER_AC_END)

                end_ok = 0;

            if ((error & ER_MV_END) ||

                (error & ER_DC_END) ||

                (error & ER_AC_ERROR))

                end_ok = 1;



            if (!end_ok)

                s->error_status_table[mb_xy]|= ER_AC_ERROR;



            if (error & VP_START)

                end_ok = 0;

        }

    }

#endif

    /* handle missing slices */

    if (s->avctx->err_recognition & AV_EF_EXPLODE) {

        int end_ok = 1;



        // FIXME + 100 hack

        for (i = s->mb_num - 2; i >= s->mb_width + 100; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int error1 = s->error_status_table[mb_xy];

            int error2 = s->error_status_table[s->mb_index2xy[i + 1]];



            if (error1 & VP_START)

                end_ok = 1;



            if (error2 == (VP_START | ER_MB_ERROR | ER_MB_END) &&

                error1 != (VP_START | ER_MB_ERROR | ER_MB_END) &&

                ((error1 & ER_AC_END) || (error1 & ER_DC_END) ||

                (error1 & ER_MV_END))) {

                // end & uninit

                end_ok = 0;

            }



            if (!end_ok)

                s->error_status_table[mb_xy] |= ER_MB_ERROR;

        }

    }



#if 1

    /* backward mark errors */

    distance = 9999999;

    for (error_type = 1; error_type <= 3; error_type++) {

        for (i = s->mb_num - 1; i >= 0; i--) {

            const int mb_xy = s->mb_index2xy[i];

            int       error = s->error_status_table[mb_xy];



            if (!s->mbskip_table[mb_xy]) // FIXME partition specific

                distance++;

            if (error & (1 << error_type))

                distance = 0;



            if (s->partitioned_frame) {

                if (distance < threshold_part[error_type - 1])

                    s->error_status_table[mb_xy] |= 1 << error_type;

            } else {

                if (distance < threshold)

                    s->error_status_table[mb_xy] |= 1 << error_type;

            }



            if (error & VP_START)

                distance = 9999999;

        }

    }

#endif



    /* forward mark errors */

    error = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int old_error   = s->error_status_table[mb_xy];



        if (old_error & VP_START) {

            error = old_error & ER_MB_ERROR;

        } else {

            error |= old_error & ER_MB_ERROR;

            s->error_status_table[mb_xy] |= error;

        }

    }

#if 1

    /* handle not partitioned case */

    if (!s->partitioned_frame) {

        for (i = 0; i < s->mb_num; i++) {

            const int mb_xy = s->mb_index2xy[i];

            error = s->error_status_table[mb_xy];

            if (error & ER_MB_ERROR)

                error |= ER_MB_ERROR;

            s->error_status_table[mb_xy] = error;

        }

    }

#endif



    dc_error = ac_error = mv_error = 0;

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        error = s->error_status_table[mb_xy];

        if (error & ER_DC_ERROR)

            dc_error++;

        if (error & ER_AC_ERROR)

            ac_error++;

        if (error & ER_MV_ERROR)

            mv_error++;

    }

    av_log(s->avctx, AV_LOG_INFO, "concealing %d DC, %d AC, %d MV errors in %c frame\n",

           dc_error, ac_error, mv_error, av_get_picture_type_char(s->cur_pic->f.pict_type));



    is_intra_likely = is_intra_more_likely(s);



    /* set unknown mb-type to most likely */

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        error = s->error_status_table[mb_xy];

        if (!((error & ER_DC_ERROR) && (error & ER_MV_ERROR)))

            continue;



        if (is_intra_likely)

            s->cur_pic->mb_type[mb_xy] = MB_TYPE_INTRA4x4;

        else

            s->cur_pic->mb_type[mb_xy] = MB_TYPE_16x16 | MB_TYPE_L0;

    }



    // change inter to intra blocks if no reference frames are available

    if (!(s->last_pic && s->last_pic->f.data[0]) &&

        !(s->next_pic && s->next_pic->f.data[0]))

        for (i = 0; i < s->mb_num; i++) {

            const int mb_xy = s->mb_index2xy[i];

            if (!IS_INTRA(s->cur_pic->mb_type[mb_xy]))

                s->cur_pic->mb_type[mb_xy] = MB_TYPE_INTRA4x4;

        }



    /* handle inter blocks with damaged AC */

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            const int mb_xy   = mb_x + mb_y * s->mb_stride;

            const int mb_type = s->cur_pic->mb_type[mb_xy];

            const int dir     = !(s->last_pic && s->last_pic->f.data[0]);

            const int mv_dir  = dir ? MV_DIR_BACKWARD : MV_DIR_FORWARD;

            int mv_type;



            error = s->error_status_table[mb_xy];



            if (IS_INTRA(mb_type))

                continue; // intra

            if (error & ER_MV_ERROR)

                continue; // inter with damaged MV

            if (!(error & ER_AC_ERROR))

                continue; // undamaged inter



            if (IS_8X8(mb_type)) {

                int mb_index = mb_x * 2 + mb_y * 2 * s->b8_stride;

                int j;

                mv_type = MV_TYPE_8X8;

                for (j = 0; j < 4; j++) {

                    s->mv[0][j][0] = s->cur_pic->motion_val[dir][mb_index + (j & 1) + (j >> 1) * s->b8_stride][0];

                    s->mv[0][j][1] = s->cur_pic->motion_val[dir][mb_index + (j & 1) + (j >> 1) * s->b8_stride][1];

                }

            } else {

                mv_type     = MV_TYPE_16X16;

                s->mv[0][0][0] = s->cur_pic->motion_val[dir][mb_x * 2 + mb_y * 2 * s->b8_stride][0];

                s->mv[0][0][1] = s->cur_pic->motion_val[dir][mb_x * 2 + mb_y * 2 * s->b8_stride][1];

            }



            s->decode_mb(s->opaque, 0 /* FIXME h264 partitioned slices need this set */,

                         mv_dir, mv_type, &s->mv, mb_x, mb_y, 0, 0);

        }

    }



    /* guess MVs */

    if (s->cur_pic->f.pict_type == AV_PICTURE_TYPE_B) {

        for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

            for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

                int       xy      = mb_x * 2 + mb_y * 2 * s->b8_stride;

                const int mb_xy   = mb_x + mb_y * s->mb_stride;

                const int mb_type = s->cur_pic->mb_type[mb_xy];

                int mv_dir = MV_DIR_FORWARD | MV_DIR_BACKWARD;



                error = s->error_status_table[mb_xy];



                if (IS_INTRA(mb_type))

                    continue;

                if (!(error & ER_MV_ERROR))

                    continue; // inter with undamaged MV

                if (!(error & ER_AC_ERROR))

                    continue; // undamaged inter



                if (!(s->last_pic && s->last_pic->f.data[0]))

                    mv_dir &= ~MV_DIR_FORWARD;

                if (!(s->next_pic && s->next_pic->f.data[0]))

                    mv_dir &= ~MV_DIR_BACKWARD;



                if (s->pp_time) {

                    int time_pp = s->pp_time;

                    int time_pb = s->pb_time;



                    av_assert0(s->avctx->codec_id != AV_CODEC_ID_H264);

                    ff_thread_await_progress(&s->next_pic->tf, mb_y, 0);



                    s->mv[0][0][0] = s->next_pic->motion_val[0][xy][0] *  time_pb            / time_pp;

                    s->mv[0][0][1] = s->next_pic->motion_val[0][xy][1] *  time_pb            / time_pp;

                    s->mv[1][0][0] = s->next_pic->motion_val[0][xy][0] * (time_pb - time_pp) / time_pp;

                    s->mv[1][0][1] = s->next_pic->motion_val[0][xy][1] * (time_pb - time_pp) / time_pp;

                } else {

                    s->mv[0][0][0] = 0;

                    s->mv[0][0][1] = 0;

                    s->mv[1][0][0] = 0;

                    s->mv[1][0][1] = 0;

                }



                s->decode_mb(s->opaque, 0, mv_dir, MV_TYPE_16X16, &s->mv,

                             mb_x, mb_y, 0, 0);

            }

        }

    } else

        guess_mv(s);



#if FF_API_XVMC

FF_DISABLE_DEPRECATION_WARNINGS

    /* the filters below are not XvMC compatible, skip them */

    if (CONFIG_MPEG_XVMC_DECODER && s->avctx->xvmc_acceleration)

        goto ec_clean;

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */

    /* fill DC for inter blocks */

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            int dc, dcu, dcv, y, n;

            int16_t *dc_ptr;

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy   = mb_x + mb_y * s->mb_stride;

            const int mb_type = s->cur_pic->mb_type[mb_xy];



            error = s->error_status_table[mb_xy];



            if (IS_INTRA(mb_type) && s->partitioned_frame)

                continue;

            // if (error & ER_MV_ERROR)

            //     continue; // inter data damaged FIXME is this good?



            dest_y  = s->cur_pic->f.data[0] + mb_x * 16 + mb_y * 16 * linesize[0];

            dest_cb = s->cur_pic->f.data[1] + mb_x *  8 + mb_y *  8 * linesize[1];

            dest_cr = s->cur_pic->f.data[2] + mb_x *  8 + mb_y *  8 * linesize[2];



            dc_ptr = &s->dc_val[0][mb_x * 2 + mb_y * 2 * s->b8_stride];

            for (n = 0; n < 4; n++) {

                dc = 0;

                for (y = 0; y < 8; y++) {

                    int x;

                    for (x = 0; x < 8; x++)

                       dc += dest_y[x + (n & 1) * 8 +

                             (y + (n >> 1) * 8) * linesize[0]];

                }

                dc_ptr[(n & 1) + (n >> 1) * s->b8_stride] = (dc + 4) >> 3;

            }



            dcu = dcv = 0;

            for (y = 0; y < 8; y++) {

                int x;

                for (x = 0; x < 8; x++) {

                    dcu += dest_cb[x + y * linesize[1]];

                    dcv += dest_cr[x + y * linesize[2]];

                }

            }

            s->dc_val[1][mb_x + mb_y * s->mb_stride] = (dcu + 4) >> 3;

            s->dc_val[2][mb_x + mb_y * s->mb_stride] = (dcv + 4) >> 3;

        }

    }

#if 1

    /* guess DC for damaged blocks */

    guess_dc(s, s->dc_val[0], s->mb_width*2, s->mb_height*2, s->b8_stride, 1);

    guess_dc(s, s->dc_val[1], s->mb_width  , s->mb_height  , s->mb_stride, 0);

    guess_dc(s, s->dc_val[2], s->mb_width  , s->mb_height  , s->mb_stride, 0);

#endif



    /* filter luma DC */

    filter181(s->dc_val[0], s->mb_width * 2, s->mb_height * 2, s->b8_stride);



#if 1

    /* render DC only intra */

    for (mb_y = 0; mb_y < s->mb_height; mb_y++) {

        for (mb_x = 0; mb_x < s->mb_width; mb_x++) {

            uint8_t *dest_y, *dest_cb, *dest_cr;

            const int mb_xy   = mb_x + mb_y * s->mb_stride;

            const int mb_type = s->cur_pic->mb_type[mb_xy];



            error = s->error_status_table[mb_xy];



            if (IS_INTER(mb_type))

                continue;

            if (!(error & ER_AC_ERROR))

                continue; // undamaged



            dest_y  = s->cur_pic->f.data[0] + mb_x * 16 + mb_y * 16 * linesize[0];

            dest_cb = s->cur_pic->f.data[1] + mb_x *  8 + mb_y *  8 * linesize[1];

            dest_cr = s->cur_pic->f.data[2] + mb_x *  8 + mb_y *  8 * linesize[2];



            put_dc(s, dest_y, dest_cb, dest_cr, mb_x, mb_y);

        }

    }

#endif



    if (s->avctx->error_concealment & FF_EC_DEBLOCK) {

        /* filter horizontal block boundaries */

        h_block_filter(s, s->cur_pic->f.data[0], s->mb_width * 2,

                       s->mb_height * 2, linesize[0], 1);

        h_block_filter(s, s->cur_pic->f.data[1], s->mb_width,

                       s->mb_height, linesize[1], 0);

        h_block_filter(s, s->cur_pic->f.data[2], s->mb_width,

                       s->mb_height, linesize[2], 0);



        /* filter vertical block boundaries */

        v_block_filter(s, s->cur_pic->f.data[0], s->mb_width * 2,

                       s->mb_height * 2, linesize[0], 1);

        v_block_filter(s, s->cur_pic->f.data[1], s->mb_width,

                       s->mb_height, linesize[1], 0);

        v_block_filter(s, s->cur_pic->f.data[2], s->mb_width,

                       s->mb_height, linesize[2], 0);

    }



ec_clean:

    /* clean a few tables */

    for (i = 0; i < s->mb_num; i++) {

        const int mb_xy = s->mb_index2xy[i];

        int       error = s->error_status_table[mb_xy];



        if (s->cur_pic->f.pict_type != AV_PICTURE_TYPE_B &&

            (error & (ER_DC_ERROR | ER_MV_ERROR | ER_AC_ERROR))) {

            s->mbskip_table[mb_xy] = 0;

        }

        s->mbintra_table[mb_xy] = 1;

    }

    s->cur_pic = NULL;

    s->next_pic    = NULL;

    s->last_pic    = NULL;

}

