            env->spr[SPR_BOOKE_MAS1] = sregs.u.e.mas1;

            env->spr[SPR_BOOKE_MAS2] = sregs.u.e.mas2;

            env->spr[SPR_BOOKE_MAS3] = sregs.u.e.mas7_3 & 0xffffffff;

            env->spr[SPR_BOOKE_MAS4] = sregs.u.e.mas4;

            env->spr[SPR_BOOKE_MAS6] = sregs.u.e.mas6;

            env->spr[SPR_BOOKE_MAS7] = sregs.u.e.mas7_3 >> 32;

            env->spr[SPR_MMUCFG] = sregs.u.e.mmucfg;

            env->spr[SPR_BOOKE_TLB0CFG] = sregs.u.e.tlbcfg[0];

            env->spr[SPR_BOOKE_TLB1CFG] = sregs.u.e.tlbcfg[1];

        }



        if (sregs.u.e.features & KVM_SREGS_EXP) {

            env->spr[SPR_BOOKE_EPR] = sregs.u.e.epr;

        }



        if (sregs.u.e.features & KVM_SREGS_E_PD) {

            env->spr[SPR_BOOKE_EPLC] = sregs.u.e.eplc;

            env->spr[SPR_BOOKE_EPSC] = sregs.u.e.epsc;

        }



        if (sregs.u.e.impl_id == KVM_SREGS_E_IMPL_FSL) {

            env->spr[SPR_E500_SVR] = sregs.u.e.impl.fsl.svr;

            env->spr[SPR_Exxx_MCAR] = sregs.u.e.impl.fsl.mcar;

            env->spr[SPR_HID0] = sregs.u.e.impl.fsl.hid0;



            if (sregs.u.e.impl.fsl.features & KVM_SREGS_E_FSL_PIDn) {

                env->spr[SPR_BOOKE_PID1] = sregs.u.e.impl.fsl.pid1;

                env->spr[SPR_BOOKE_PID2] = sregs.u.e.impl.fsl.pid2;

            }

        }

    }



    if (cap_segstate) {

        ret = kvm_vcpu_ioctl(cs, KVM_GET_SREGS, &sregs);

        if (ret < 0) {

            return ret;

        }



        ppc_store_sdr1(env, sregs.u.s.sdr1);



        /* Sync SLB */

#ifdef TARGET_PPC64

        /*

         * The packed SLB array we get from KVM_GET_SREGS only contains

         * information about valid entries. So we flush our internal

         * copy to get rid of stale ones, then put all valid SLB entries

         * back in.

         */

        memset(env->slb, 0, sizeof(env->slb));

        for (i = 0; i < ARRAY_SIZE(env->slb); i++) {

            target_ulong rb = sregs.u.s.ppc64.slb[i].slbe;

            target_ulong rs = sregs.u.s.ppc64.slb[i].slbv;

            /*

             * Only restore valid entries

             */

            if (rb & SLB_ESID_V) {

                ppc_store_slb(env, rb, rs);

            }

        }

#endif



        /* Sync SRs */

        for (i = 0; i < 16; i++) {

            env->sr[i] = sregs.u.s.ppc32.sr[i];

        }



        /* Sync BATs */

        for (i = 0; i < 8; i++) {

            env->DBAT[0][i] = sregs.u.s.ppc32.dbat[i] & 0xffffffff;

            env->DBAT[1][i] = sregs.u.s.ppc32.dbat[i] >> 32;

            env->IBAT[0][i] = sregs.u.s.ppc32.ibat[i] & 0xffffffff;

            env->IBAT[1][i] = sregs.u.s.ppc32.ibat[i] >> 32;

        }

    }



    if (cap_hior) {

        kvm_get_one_spr(cs, KVM_REG_PPC_HIOR, SPR_HIOR);

    }



    if (cap_one_reg) {

        int i;



        /* We deliberately ignore errors here, for kernels which have

         * the ONE_REG calls, but don't support the specific

         * registers, there's a reasonable chance things will still

         * work, at least until we try to migrate. */

        for (i = 0; i < 1024; i++) {

            uint64_t id = env->spr_cb[i].one_reg_id;



            if (id != 0) {

                kvm_get_one_spr(cs, id, i);

            }

        }



#ifdef TARGET_PPC64

        if (cap_papr) {

            if (kvm_get_vpa(cs) < 0) {

                DPRINTF("Warning: Unable to get VPA information from KVM\n");

            }

        }

#endif

    }



    return 0;

}

int kvmppc_put_books_sregs(PowerPCCPU *cpu)

{

    CPUPPCState *env = &cpu->env;

    struct kvm_sregs sregs;

    int i;



    sregs.pvr = env->spr[SPR_PVR];



    sregs.u.s.sdr1 = env->spr[SPR_SDR1];



    /* Sync SLB */

#ifdef TARGET_PPC64

    for (i = 0; i < ARRAY_SIZE(env->slb); i++) {

        sregs.u.s.ppc64.slb[i].slbe = env->slb[i].esid;

        if (env->slb[i].esid & SLB_ESID_V) {

            sregs.u.s.ppc64.slb[i].slbe |= i;

        }

        sregs.u.s.ppc64.slb[i].slbv = env->slb[i].vsid;

    }

#endif



    /* Sync SRs */

    for (i = 0; i < 16; i++) {

        sregs.u.s.ppc32.sr[i] = env->sr[i];

    }



    /* Sync BATs */

    for (i = 0; i < 8; i++) {

        /* Beware. We have to swap upper and lower bits here */

        sregs.u.s.ppc32.dbat[i] = ((uint64_t)env->DBAT[0][i] << 32)

            | env->DBAT[1][i];

        sregs.u.s.ppc32.ibat[i] = ((uint64_t)env->IBAT[0][i] << 32)

            | env->IBAT[1][i];

    }



    return kvm_vcpu_ioctl(CPU(cpu), KVM_SET_SREGS, &sregs);

}

