            if( is_dc ) { \

                ((type*)block)[j] = get_cabac_bypass_sign( CC, -coeff_abs ); \

            }else{ \

                ((type*)block)[j] = ((int)(get_cabac_bypass_sign( CC, -coeff_abs ) * qmul[j] + 32)) >> 6; \

            } \

        } \

    } while ( coeff_count );



    if (h->pixel_shift) {

        STORE_BLOCK(int32_t)

    } else {

        STORE_BLOCK(int16_t)

    }

