static int ftp_passive_mode(FTPContext *s)

{

    char *res = NULL, *start, *end;

    int i;

    const char *command = "PASV\r\n";

    const int pasv_codes[] = {227, 501, 0}; /* 501 is incorrect code */



    if (ftp_send_command(s, command, pasv_codes, &res) != 227 || !res)

        goto fail;



    start = NULL;

    for (i = 0; i < strlen(res); ++i) {

        if (res[i] == '(') {

            start = res + i + 1;

        } else if (res[i] == ')') {

            end = res + i;

            break;

        }

    }

    if (!start || !end)

        goto fail;



    *end  = '\0';

    /* skip ip */

    if (!av_strtok(start, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;

    if (!av_strtok(end, ",", &end)) goto fail;



    /* parse port number */

    start = av_strtok(end, ",", &end);

    if (!start) goto fail;

    s->server_data_port = atoi(start) * 256;

    start = av_strtok(end, ",", &end);

    if (!start) goto fail;

    s->server_data_port += atoi(start);

    av_dlog(s, "Server data port: %d\n", s->server_data_port);



    av_free(res);

    return 0;



  fail:

    av_free(res);

    s->server_data_port = -1;

    return AVERROR(EIO);

}

SocketAddress *socket_parse(const char *str, Error **errp)

{

    SocketAddress *addr;



    addr = g_new0(SocketAddress, 1);

    if (strstart(str, "unix:", NULL)) {

        if (str[5] == '\0') {

            error_setg(errp, "invalid Unix socket address");

            goto fail;

        } else {

            addr->type = SOCKET_ADDRESS_KIND_UNIX;

            addr->u.q_unix.data = g_new(UnixSocketAddress, 1);

            addr->u.q_unix.data->path = g_strdup(str + 5);

        }

    } else if (strstart(str, "fd:", NULL)) {

        if (str[3] == '\0') {

            error_setg(errp, "invalid file descriptor address");

            goto fail;

        } else {

            addr->type = SOCKET_ADDRESS_KIND_FD;

            addr->u.fd.data = g_new(String, 1);

            addr->u.fd.data->str = g_strdup(str + 3);

        }

    } else if (strstart(str, "vsock:", NULL)) {

        addr->type = SOCKET_ADDRESS_KIND_VSOCK;

        addr->u.vsock.data = g_new(VsockSocketAddress, 1);

        if (vsock_parse(addr->u.vsock.data, str + strlen("vsock:"), errp)) {

            goto fail;

        }

    } else {

        addr->type = SOCKET_ADDRESS_KIND_INET;

        addr->u.inet.data = g_new(InetSocketAddress, 1);

        if (inet_parse(addr->u.inet.data, str, errp)) {

            goto fail;

        }

    }

    return addr;



fail:

    qapi_free_SocketAddress(addr);

    return NULL;

}

